DO $precondition$
DECLARE
  missing_templates TEXT;
  missing_rows TEXT;
  conflicts TEXT;
BEGIN
  SELECT string_agg(p.template_code, ', ' ORDER BY p.template_code)
    INTO missing_templates
  FROM (SELECT DISTINCT template_code FROM formula_cell_patch) p
  LEFT JOIN calc.cabinet_template t ON t.template_code = p.template_code
  WHERE t.template_id IS NULL;
  IF missing_templates IS NOT NULL THEN
    RAISE EXCEPTION 'Missing formula templates: %', missing_templates;
  END IF;

  SELECT string_agg(format('%s row %s', p.template_code, p.source_row_no), ', '
                    ORDER BY p.template_code, p.source_row_no)
    INTO missing_rows
  FROM (SELECT DISTINCT template_code, source_row_no FROM formula_cell_patch) p
  JOIN calc.cabinet_template t ON t.template_code = p.template_code
  LEFT JOIN calc.cabinet_part_rule r
    ON r.template_id = t.template_id AND r.source_row_no = p.source_row_no
  WHERE r.rule_id IS NULL;
  IF missing_rows IS NOT NULL THEN
    RAISE EXCEPTION 'Missing formula rows: %', missing_rows;
  END IF;

  SELECT string_agg(format('%s!%s', p.template_code, p.source_cell), ', '
                    ORDER BY p.template_code, p.source_row_no, p.formula_index)
    INTO conflicts
  FROM formula_cell_patch p
  JOIN calc.cabinet_template t ON t.template_code = p.template_code
  JOIN calc.cabinet_part_rule r
    ON r.template_id = t.template_id AND r.source_row_no = p.source_row_no
  WHERE COALESCE(r.raw_rule->'formulas'->>p.formula_index, '') NOT IN ('', p.formula_text);
  IF conflicts IS NOT NULL THEN
    RAISE EXCEPTION 'Existing formula conflicts: %', conflicts;
  END IF;
END;
$precondition$;

UPDATE calc.cabinet_part_rule r
SET raw_rule = jsonb_set(
      COALESCE(r.raw_rule, '{}'::jsonb),
      '{formulas}',
      (
        SELECT jsonb_agg(
          COALESCE(to_jsonb(p.formula_text), r.raw_rule->'formulas'->g.formula_index, '""'::jsonb)
          ORDER BY g.formula_index
        )
        FROM generate_series(0, 22) AS g(formula_index)
        LEFT JOIN formula_cell_patch p
          ON p.template_code = t.template_code
         AND p.source_row_no = r.source_row_no
         AND p.formula_index = g.formula_index
      ),
      TRUE
    ),
    condition_formula = COALESCE((SELECT p.formula_text FROM formula_cell_patch p WHERE p.template_code = t.template_code AND p.source_row_no = r.source_row_no AND p.formula_index = 22), r.condition_formula),
    length_formula = COALESCE((SELECT p.formula_text FROM formula_cell_patch p WHERE p.template_code = t.template_code AND p.source_row_no = r.source_row_no AND p.formula_index = 2), r.length_formula),
    width_formula = COALESCE((SELECT p.formula_text FROM formula_cell_patch p WHERE p.template_code = t.template_code AND p.source_row_no = r.source_row_no AND p.formula_index = 3), r.width_formula),
    thickness_formula = COALESCE((SELECT p.formula_text FROM formula_cell_patch p WHERE p.template_code = t.template_code AND p.source_row_no = r.source_row_no AND p.formula_index = 4), r.thickness_formula),
    density_formula = COALESCE((SELECT p.formula_text FROM formula_cell_patch p WHERE p.template_code = t.template_code AND p.source_row_no = r.source_row_no AND p.formula_index = 5), r.density_formula),
    single_quantity_formula = COALESCE((SELECT p.formula_text FROM formula_cell_patch p WHERE p.template_code = t.template_code AND p.source_row_no = r.source_row_no AND p.formula_index = 7), r.single_quantity_formula),
    total_quantity_formula = COALESCE((SELECT p.formula_text FROM formula_cell_patch p WHERE p.template_code = t.template_code AND p.source_row_no = r.source_row_no AND p.formula_index = 8), r.total_quantity_formula),
    weight_formula = COALESCE((SELECT p.formula_text FROM formula_cell_patch p WHERE p.template_code = t.template_code AND p.source_row_no = r.source_row_no AND p.formula_index = 9), r.weight_formula),
    area_formula = COALESCE((SELECT p.formula_text FROM formula_cell_patch p WHERE p.template_code = t.template_code AND p.source_row_no = r.source_row_no AND p.formula_index = 21), r.area_formula)
FROM calc.cabinet_template t
WHERE r.template_id = t.template_id
  AND EXISTS (
    SELECT 1 FROM formula_cell_patch p
    WHERE p.template_code = t.template_code
      AND p.source_row_no = r.source_row_no
  );

DO $postcondition$
DECLARE
  mismatch TEXT;
BEGIN
  SELECT string_agg(format('%s!%s', p.template_code, p.source_cell), ', '
                    ORDER BY p.template_code, p.source_row_no, p.formula_index)
    INTO mismatch
  FROM formula_cell_patch p
  JOIN calc.cabinet_template t ON t.template_code = p.template_code
  JOIN calc.cabinet_part_rule r
    ON r.template_id = t.template_id AND r.source_row_no = p.source_row_no
  WHERE r.raw_rule->'formulas'->>p.formula_index IS DISTINCT FROM p.formula_text;
  IF mismatch IS NOT NULL THEN
    RAISE EXCEPTION 'Formula completion mismatch: %', mismatch;
  END IF;
END;
$postcondition$;

COMMIT;
